import{_ as t,o as l,c as a,a4 as i}from"./chunks/framework.vNSRaLQv.js";const b=JSON.parse('{"title":"折腾日志 2026-06-29","description":"","frontmatter":{"title":"折腾日志 2026-06-29","date":"2026-06-29T00:00:00.000Z"},"headers":[],"relativePath":"posts/操作记录_20260629.md","filePath":"posts/操作记录_20260629.md"}'),o={name:"posts/操作记录_20260629.md"};function d(r,e,h,c,n,s){return l(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="折腾日志-2026-06-29" tabindex="-1">折腾日志 2026-06-29 <a class="header-anchor" href="#折腾日志-2026-06-29" aria-label="Permalink to &quot;折腾日志 2026-06-29&quot;">​</a></h1><blockquote><p>记录一整天的操作：从手机去 bloated → 变砖 → 抢救照片 → 跨设备迁移</p></blockquote><hr><h2 id="一、开局-adb-屠龙" tabindex="-1">一、开局：ADB 屠龙 <a class="header-anchor" href="#一、开局-adb-屠龙" aria-label="Permalink to &quot;一、开局：ADB 屠龙&quot;">​</a></h2><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>旧手机 A 预装软件太多，打算卸干净当服务器用。</p><h3 id="方式" tabindex="-1">方式 <a class="header-anchor" href="#方式" aria-label="Permalink to &quot;方式&quot;">​</a></h3><p><code>adb shell pm uninstall -k --user 0 &lt;pkg&gt;</code></p><h3 id="卸载范围-多轮" tabindex="-1">卸载范围（多轮） <a class="header-anchor" href="#卸载范围-多轮" aria-label="Permalink to &quot;卸载范围（多轮）&quot;">​</a></h3><ul><li>预装商店、浏览器、音乐、视频、阅读</li><li>华为云、钱包、推送</li><li>搜索、语音助手、游戏服务</li><li>日历、闹钟、媒体中心</li><li>短信、彩信、下载管理器</li><li>蓝牙、WiFi 相关</li><li>各类框架（HMS、HIAI、HiView...）</li><li>安全中心、省电管理、设备管理</li></ul><h3 id="卸载统计" tabindex="-1">卸载统计 <a class="header-anchor" href="#卸载统计" aria-label="Permalink to &quot;卸载统计&quot;">​</a></h3><p>累计卸载约 100+ 个包，全部返回 <code>Success</code></p><hr><h2 id="二、作死-卸了不该卸的" tabindex="-1">二、作死：卸了不该卸的 <a class="header-anchor" href="#二、作死-卸了不该卸的" aria-label="Permalink to &quot;二、作死：卸了不该卸的&quot;">​</a></h2><h3 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to &quot;操作&quot;">​</a></h3><p>继续卸载电话/通讯相关包：</p><ul><li><code>com.android.phone</code></li><li><code>com.android.server.telecom</code></li><li><code>com.android.incallui</code></li><li><code>com.android.contacts</code></li><li><code>com.android.providers.telephony</code></li><li><code>com.huawei.ims</code></li></ul><h3 id="结果" tabindex="-1">结果 <a class="header-anchor" href="#结果" aria-label="Permalink to &quot;结果&quot;">​</a></h3><p>手机重启后卡在 Logo 界面 → <strong>boot loop，变砖</strong></p><h3 id="教训" tabindex="-1">教训 <a class="header-anchor" href="#教训" aria-label="Permalink to &quot;教训&quot;">​</a></h3><ul><li><code>pm uninstall --user 0</code> 只移除当前用户可见部分，但安卓系统服务被移除后无法启动</li><li>部分系统应用（phone、telecom）是核心组件，卸了直接崩</li><li>进 recovery 可访问文件系统，但无法正常启动</li></ul><hr><h2 id="三、抢救-取出照片" tabindex="-1">三、抢救：取出照片 <a class="header-anchor" href="#三、抢救-取出照片" aria-label="Permalink to &quot;三、抢救：取出照片&quot;">​</a></h2><h3 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h3><ol><li>按住音量上 + 电源 → 进入 eRecovery 模式</li><li>通过 MTP 连接电脑 → 手机存储显示为移动设备</li><li>手动拷贝照片到 PC</li></ol><h3 id="备份范围" tabindex="-1">备份范围 <a class="header-anchor" href="#备份范围" aria-label="Permalink to &quot;备份范围&quot;">​</a></h3><p>仅 Camera（相机照片）+ Screenshots（截图），2023 年+ 跳过 QQ / 微信等聊天图片文件夹</p><hr><h2 id="四、接盘-连上新手机" tabindex="-1">四、接盘：连上新手机 <a class="header-anchor" href="#四、接盘-连上新手机" aria-label="Permalink to &quot;四、接盘：连上新手机&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>数据曾从旧手机 A 迁移到新手机 B，但迁移不完整</p><h3 id="连接" tabindex="-1">连接 <a class="header-anchor" href="#连接" aria-label="Permalink to &quot;连接&quot;">​</a></h3><p><code>adb connect 192.168.31.x:5555</code> — 无线 ADB</p><h3 id="对比方式" tabindex="-1">对比方式 <a class="header-anchor" href="#对比方式" aria-label="Permalink to &quot;对比方式&quot;">​</a></h3><ol><li><code>adb shell ls</code> 枚举 B 手机文件</li><li>MTP Shell.Application 枚举 A 手机文件</li><li>PowerShell <code>Where-Object { $B -notcontains $_ }</code> 找差异</li><li>缺失文件从 A 的 MTP → PC 临时目录 → <code>adb push</code> → B 手机</li></ol><h3 id="同步范围" tabindex="-1">同步范围 <a class="header-anchor" href="#同步范围" aria-label="Permalink to &quot;同步范围&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">目录</th><th style="text-align:left;">结果</th></tr></thead><tbody><tr><td style="text-align:left;">DCIM/Camera</td><td style="text-align:left;">补推约 140 张（2022–2023 缺失）</td></tr><tr><td style="text-align:left;">Pictures/Screenshots</td><td style="text-align:left;">补推 66 张</td></tr><tr><td style="text-align:left;">Pictures/新建相册</td><td style="text-align:left;">补推 72 张（原为空）</td></tr><tr><td style="text-align:left;">其他相册（~6个）</td><td style="text-align:left;">补推约 15 张</td></tr><tr><td style="text-align:left;">QQ/微信</td><td style="text-align:left;">跳过（按指示）</td></tr></tbody></table><hr><h2 id="五、踩坑记录" tabindex="-1">五、踩坑记录 <a class="header-anchor" href="#五、踩坑记录" aria-label="Permalink to &quot;五、踩坑记录&quot;">​</a></h2><h3 id="_1-adb-中文路径编码-bug" tabindex="-1">1. ADB 中文路径编码 bug <a class="header-anchor" href="#_1-adb-中文路径编码-bug" aria-label="Permalink to &quot;1. ADB 中文路径编码 bug&quot;">​</a></h3><ul><li>现象：<code>adb push xxx.jpg /sdcard/Pictures/中文目录/</code> 后，文件名被截断</li><li>如 <code>IMG_20230720_095918.jpg</code> → <code>IMG_20230720_0959</code></li><li>原因：ADB 协议在传输中文路径时发生编码截断</li><li>解决：出现残缺文件后 <code>rm -rf</code> 清空重建，重新推送</li></ul><h3 id="_2-mtp-文件访问极慢" tabindex="-1">2. MTP 文件访问极慢 <a class="header-anchor" href="#_2-mtp-文件访问极慢" aria-label="Permalink to &quot;2. MTP 文件访问极慢&quot;">​</a></h3><ul><li>Windows Shell.Application COM 对象访问 MTP 设备，每枚举一次 10~30s</li><li>大目录（200+文件）容易超时</li><li>策略：分批读取、保存列表到文件后离线比对</li></ul><h3 id="_3-文件名特殊字符转义" tabindex="-1">3. 文件名特殊字符转义 <a class="header-anchor" href="#_3-文件名特殊字符转义" aria-label="Permalink to &quot;3. 文件名特殊字符转义&quot;">​</a></h3><ul><li><code>[]</code> <code>()</code> 空格在 adb shell 中有特殊含义</li><li><code>mv</code> 操作需要转义或使用 <code>cat &gt;</code> 重定向</li></ul><h3 id="_4-powershell-中文编码" tabindex="-1">4. PowerShell 中文编码 <a class="header-anchor" href="#_4-powershell-中文编码" aria-label="Permalink to &quot;4. PowerShell 中文编码&quot;">​</a></h3><ul><li>中文目录/文件名在控制台输出乱码，影响调试</li><li><code>ls</code> 结果与 <code>find -type f</code> 结果可能不一致</li><li>改用 <code>find ... -exec basename</code> 获取纯净文件名</li></ul><hr><h2 id="六、当前状态" tabindex="-1">六、当前状态 <a class="header-anchor" href="#六、当前状态" aria-label="Permalink to &quot;六、当前状态&quot;">​</a></h2><ul><li>[x] 旧手机照片已全部备份到 PC</li><li>[x] 旧手机照片已完整同步到新手机 B</li><li>[ ] 旧手机仍变砖（卡 logo，boot loop）</li></ul><hr><h2 id="七、待办" tabindex="-1">七、待办 <a class="header-anchor" href="#七、待办" aria-label="Permalink to &quot;七、待办&quot;">​</a></h2><ol><li>救旧手机 —— 方案： <ul><li>官方 HiSuite 系统修复</li><li>eRecovery 在线恢复</li><li>恢复出厂设置（照片已安全，可接受）</li></ul></li><li>救活后安装 Termux，搭建服务器环境</li></ol><hr><h2 id="八、技术备忘" tabindex="-1">八、技术备忘 <a class="header-anchor" href="#八、技术备忘" aria-label="Permalink to &quot;八、技术备忘&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">命令/方法</th></tr></thead><tbody><tr><td style="text-align:left;">卸载应用</td><td style="text-align:left;"><code>pm uninstall -k --user 0 &lt;pkg&gt;</code></td></tr><tr><td style="text-align:left;">恢复应用</td><td style="text-align:left;"><code>pm install-existing &lt;pkg&gt;</code></td></tr><tr><td style="text-align:left;">无线 ADB 连接</td><td style="text-align:left;"><code>adb connect &lt;ip&gt;:5555</code></td></tr><tr><td style="text-align:left;">MTP 编程访问</td><td style="text-align:left;"><code>Shell.Application</code> COM 对象</td></tr><tr><td style="text-align:left;">MTP 文件拷贝</td><td style="text-align:left;"><code>folder.CopyHere(item, 0x14)</code></td></tr><tr><td style="text-align:left;">文件列表保存</td><td style="text-align:left;"><code>list | Out-File path.txt</code></td></tr><tr><td style="text-align:left;">文件名比对</td><td style="text-align:left;"><code>$A | Where-Object { $B -notcontains $_ }</code></td></tr><tr><td style="text-align:left;">push 到中文目录</td><td style="text-align:left;">尽量避免，或用 <code>cat</code> + <code>mv</code> 替代</td></tr><tr><td style="text-align:left;">列出目录文件</td><td style="text-align:left;"><code>find /path -type f</code></td></tr></tbody></table>',56)])])}const x=t(o,[["render",d]]);export{b as __pageData,x as default};
